pragma solidity ^0.8.0;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {IVERentalEscrow} from "./interfaces/IVERentalEscrow.sol";
import {IVERentalMarketplace} from "./interfaces/IVERentalMarketplace.sol";
import {IVERental} from "./interfaces/IVERental.sol";
import {IVotingEscrow} from "./interfaces/IVotingEscrow.sol";
import {IVoter} from "./interfaces/IVoter.sol";
import {IReward} from "./interfaces/IReward.sol";
import {BaseTransfer} from "./base/BaseTransfer.sol";

contract VERentalEscrow is IVERentalEscrow, IERC721Receiver, BaseTransfer {
    address public paymentToken;
    address public factory;

    address[] public votedPools;

    uint256 public tokenId;
    uint256 public trackedPTBalance;
    uint256 public immutable sellerCommission;
    uint256 public constant HUNDRED_PERCENT = 10000;

    IVoter public voter;

    bool private _isClosed;

    constructor(address _paymentToken, uint256 _tokenId) BaseTransfer() {
        paymentToken = _paymentToken;
        tokenId = _tokenId;
        factory = msg.sender;

        voter = IVoter(
            IVotingEscrow(IVERentalMarketplace(factory).ve()).voter()
        );

        sellerCommission = IVERental(factory).rewardsCommission();
    }

    function increaseTrackedBalance(uint256 amount) public {
        if (msg.sender != factory) revert OnlyFactory();

        trackedPTBalance += amount;
    }

    function delegateVote(
        address[] calldata pools,
        uint256[] calldata weights
    ) external {
        if (msg.sender != factory) revert OnlyFactory();

        uint256 currentEpoch = IVERental(factory).currentEpoch();
        uint256 lastVoteEpoch = IVERental(factory).lastVoteEpoch();
        uint256 expiryEpoch = IVERental(factory).expiryEpoch();

        if (currentEpoch == lastVoteEpoch) revert OnlyNewEpoch();
        if (currentEpoch >= expiryEpoch) revert ExpiryEpoch();

        uint256 buyEpoch = IVERental(factory).buyEpoch();
        uint256 multiplier = lastVoteEpoch == 0
            ? (currentEpoch >= buyEpoch ? (currentEpoch - buyEpoch) + 1 : 1)
            : currentEpoch - lastVoteEpoch;
        uint256 rentDue = multiplier * IVERental(factory).price();

        trackedPTBalance -= rentDue;
        _transferERC20(paymentToken, IVERental(factory).seller(), rentDue);

        voter.vote(tokenId, pools, weights);
        _trackPools(pools);
    }

    function claim() external {
        if (msg.sender != factory) revert OnlyFactory();

        // Claim rewards
        _claimGaugeRewards();
        _claimBribeRewards();
        _claimFeeRewards();

        // Release rewards
        _releaseMGN();
        _releaseBribeRewards();
        _releaseFeeRewards();
    }

    function close() external {
        if (msg.sender != factory) revert OnlyFactory();

        require(!_isClosed, "Already closed");

        address seller = IVERental(factory).seller();
        address buyer = IVERental(factory).buyer();

        if (trackedPTBalance > 0) {
            _transferERC20(paymentToken, buyer, trackedPTBalance); // Send back remaining balance to buyer
            trackedPTBalance = 0;
        }

        IVotingEscrow(IVERentalMarketplace(factory).ve()).safeTransferFrom(
            address(this),
            seller,
            tokenId
        );

        _isClosed = true;
    }

    function _claimGaugeRewards() internal {
        address[] memory gauges = new address[](votedPools.length);

        for (uint i = 0; i < votedPools.length; i++) {
            gauges[i] = voter.gauges(votedPools[i]);
        }

        voter.claimRewards(gauges);
    }

    function _claimBribeRewards() internal {
        address[] memory bribes = new address[](votedPools.length);

        for (uint i = 0; i < votedPools.length; i++) {
            address gauge = voter.gauges(votedPools[i]);
            bribes[i] = voter.gaugeToBribe(gauge);
        }

        address[][] memory rewardTokens = new address[][](bribes.length);

        for (uint i = 0; i < bribes.length; i++) {
            uint256 tokensLength = IReward(bribes[i]).rewardsListLength();
            rewardTokens[i] = new address[](tokensLength);

            for (uint j = 0; j < tokensLength; j++) {
                rewardTokens[i][j] = IReward(bribes[i]).rewards(j);
            }
        }

        voter.claimBribes(bribes, rewardTokens, tokenId);
    }

    function _claimFeeRewards() internal {
        address[] memory fees = new address[](votedPools.length);

        for (uint i = 0; i < votedPools.length; i++) {
            address gauge = voter.gauges(votedPools[i]);
            fees[i] = voter.gaugeToFees(gauge);
        }

        address[][] memory rewardTokens = new address[][](fees.length);

        for (uint i = 0; i < fees.length; i++) {
            uint256 tokensLength = IReward(fees[i]).rewardsListLength();
            rewardTokens[i] = new address[](tokensLength);

            for (uint j = 0; j < tokensLength; j++) {
                rewardTokens[i][j] = IReward(fees[i]).rewards(j);
            }
        }

        voter.claimFees(fees, rewardTokens, tokenId);
    }

    function _releaseMGN() internal {
        address mgn = IVotingEscrow(IVERentalMarketplace(factory).ve()).token();
        // Get balance
        uint256 tokenBalance = IERC20(mgn).balanceOf(address(this));
        // Update token balance if reward token is payment token
        if (mgn == paymentToken) {
            tokenBalance -= trackedPTBalance;
        }

        // Calculate seller's portion in reward
        uint256 sellerPortion = (sellerCommission * tokenBalance) /
            HUNDRED_PERCENT;

        // Seller
        address seller = IVERental(factory).seller();

        // Buyer
        address buyer = IVERental(factory).buyer();
        // Send out reward
        _transferERC20(mgn, buyer, tokenBalance - sellerPortion);
        // Send out commission
        _transferERC20(mgn, seller, sellerPortion);
    }

    function _releaseBribeRewards() internal {
        address[] memory bribes = new address[](votedPools.length);

        for (uint i = 0; i < votedPools.length; i++) {
            address gauge = voter.gauges(votedPools[i]);
            bribes[i] = voter.gaugeToBribe(gauge);
        }

        for (uint i = 0; i < bribes.length; i++) {
            uint256 tokensLength = IReward(bribes[i]).rewardsListLength();

            for (uint j = 0; j < tokensLength; j++) {
                address reward = IReward(bribes[i]).rewards(j);
                // Get balance
                uint256 tokenBalance = IERC20(reward).balanceOf(address(this));
                // Update token balance if reward token is payment token
                if (reward == paymentToken) {
                    tokenBalance -= trackedPTBalance;
                }
                // Calculate seller's portion in reward
                uint256 sellerPortion = (sellerCommission * tokenBalance) /
                    HUNDRED_PERCENT;

                // Seller
                address seller = IVERental(factory).seller();

                // Buyer
                address buyer = IVERental(factory).buyer();
                // Send out reward
                _transferERC20(reward, buyer, tokenBalance - sellerPortion);
                // Send out commission
                _transferERC20(reward, seller, sellerPortion);
            }
        }
    }

    function _releaseFeeRewards() internal {
        address[] memory fees = new address[](votedPools.length);

        for (uint i = 0; i < votedPools.length; i++) {
            address gauge = voter.gauges(votedPools[i]);
            fees[i] = voter.gaugeToFees(gauge);
        }

        for (uint i = 0; i < fees.length; i++) {
            uint256 tokensLength = IReward(fees[i]).rewardsListLength();

            for (uint j = 0; j < tokensLength; j++) {
                address reward = IReward(fees[i]).rewards(j);
                // Get balance
                uint256 tokenBalance = IERC20(reward).balanceOf(address(this));
                // Update token balance if reward token is payment token
                if (reward == paymentToken) {
                    tokenBalance -= trackedPTBalance;
                }
                // Calculate seller's portion in reward
                uint256 sellerPortion = (sellerCommission * tokenBalance) /
                    HUNDRED_PERCENT;

                // Seller
                address seller = IVERental(factory).seller();

                // Buyer
                address buyer = IVERental(factory).buyer();
                // Send out reward
                _transferERC20(reward, buyer, tokenBalance - sellerPortion);
                // Send out commission
                _transferERC20(reward, seller, sellerPortion);
            }
        }
    }

    function _trackPools(address[] memory _pools) internal {
        for (uint i = 0; i < _pools.length; i++) {
            if (_checkPoolTracked(_pools[i])) {
                continue;
            }
            require(votedPools.length < 20, "Max pools reached");
            votedPools.push(_pools[i]);
        }
    }

    function _checkPoolTracked(address pool) internal view returns (bool) {
        for (uint i = 0; i < votedPools.length; i++) {
            if (votedPools[i] == pool) {
                return true;
            }
        }

        return false;
    }

    function onERC721Received(
        address /*operator*/,
        address /*from*/,
        uint256 /*tokenId*/,
        bytes calldata /*data*/
    ) external pure override returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }
}

src/VERentalMarketplace.sol.content:
pragma solidity ^0.8.0;

import {IVERentalMarketplace} from "./interfaces/IVERentalMarketplace.sol";
import {BaseTransfer} from "./base/BaseTransfer.sol";
import {IVERental} from "./interfaces/IVERental.sol";
import {IVotingEscrow} from "./interfaces/IVotingEscrow.sol";
import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

contract VERentalMarketplace is IVERentalMarketplace, BaseTransfer, Ownable {
    address public rentalImpl;
    address public ve;
    address[] public allRentals;

    uint256 public nonce;

    constructor(
        address _rentalImpl,
        address _ve
    ) BaseTransfer() Ownable(msg.sender) {
        rentalImpl = _rentalImpl;
        ve = _ve;
    }

    function createRental(
        uint256 tokenId,
        address paymentToken,
        uint256 price,
        uint256 duration,
        uint256 rewardsCommission
    ) public returns (address rental) {
        address sender = msg.sender;

        nonce++;

        bytes32 salt = keccak256(abi.encodePacked(tokenId, nonce));
        rental = Clones.cloneDeterministic(rentalImpl, salt);

        IVERental(rental).initialize(
            sender,
            paymentToken,
            tokenId,
            price,
            duration,
            rewardsCommission
        );

        address escrow = IVERental(rental).escrow();
        IVotingEscrow(ve).safeTransferFrom(sender, escrow, tokenId);

        allRentals.push(rental);

        emit NewRental(
            rental,
            escrow,
            tokenId,
            paymentToken,
            price,
            duration,
            rewardsCommission
        );
    }

    function createRentals(
        uint256[] memory tokenIds,
        address[] memory paymentTokens,
        uint256[] memory prices,
        uint256[] memory durations,
        uint256[] memory rewardsCommissions
    ) external returns (address[] memory rentals) {
        require(
            tokenIds.length == paymentTokens.length &&
                paymentTokens.length == prices.length &&
                prices.length == durations.length,
            "LENGTHs"
        );

        rentals = new address[](tokenIds.length);

        for (uint i = 0; i < tokenIds.length; i++) {
            uint256 tokenId = tokenIds[i];
            address paymentToken = paymentTokens[i];
            uint256 price = prices[i];
            uint256 duration = durations[i];            
            uint256 rewardsCommission = rewardsCommissions[i];

            address rental = createRental(
                tokenId,
                paymentToken,
                price,
                duration,
                rewardsCommission
            );
            rentals[i] = rental;
        }
    }

    function getAllRentals() external view returns (address[] memory) {
        return allRentals;
    }

    function withdrawAsset(
        address asset,
        address to,
        uint256 amount
    ) external onlyOwner {
        if (asset == address(0)) {
            _transferNative(to, amount);
        } else {
            _transferERC20(asset, to, amount);
        }
    }
}

src/base/BaseTransfer.sol.content:
pragma solidity ^0.8.0;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

abstract contract BaseTransfer {
    using SafeERC20 for IERC20;

    error ZeroAddress();
    error AmountIsZero();
    error NotContract();

    function _transferERC20(
        address tokenAddress,
        address to,
        uint256 amount
    ) internal {
        if (tokenAddress == address(0)) revert ZeroAddress();
        if (to == address(0)) revert ZeroAddress();
        if (tokenAddress.code.length == 0) revert NotContract();
        if (amount == 0) return;

        IERC20(tokenAddress).safeTransfer(to, amount);
    }

    function _transferFromERC20(
        address tokenAddress,
        address from,
        address to,
        uint256 amount
    ) internal {
        if (tokenAddress == address(0)) revert ZeroAddress();
        if (from == address(0)) revert ZeroAddress();
        if (to == address(0)) revert ZeroAddress();
        if (tokenAddress.code.length == 0) revert NotContract();
        if (amount == 0) return;

        IERC20(tokenAddress).safeTransferFrom(from, to, amount);
    }

    function _transferNative(address to, uint256 amount) internal {
        if (to == address(0)) revert ZeroAddress();
        if (amount == 0) return;
        (bool sent, ) = to.call{value: amount}("");
        require(sent, "Could not send out ether");
    }
}

src/interfaces/IReward.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IReward {
    error InvalidReward();
    error NotAuthorized();
    error NotGauge();
    error NotEscrowToken();
    error NotSingleToken();
    error NotVotingEscrow();
    error NotWhitelisted();
    error ZeroAmount();

    event Deposit(
        address indexed from,
        uint256 indexed tokenId,
        uint256 amount
    );
    event Withdraw(
        address indexed from,
        uint256 indexed tokenId,
        uint256 amount
    );
    event NotifyReward(
        address indexed from,
        address indexed reward,
        uint256 indexed epoch,
        uint256 amount
    );
    event ClaimRewards(
        address indexed from,
        address indexed reward,
        uint256 amount
    );

    /// @notice A checkpoint for marking balance
    struct Checkpoint {
        uint256 timestamp;
        uint256 balanceOf;
    }

    /// @notice A checkpoint for marking supply
    struct SupplyCheckpoint {
        uint256 timestamp;
        uint256 supply;
    }

    /// @notice Returns a reward token at index
    function rewards(uint256 index) external view returns (address);

    /// @notice Epoch duration constant (7 days)
    function DURATION() external view returns (uint256);

    /// @notice Address of Voter.sol
    function voter() external view returns (address);

    /// @notice Address of VotingEscrow.sol
    function ve() external view returns (address);

    /// @dev Address which has permission to externally call _deposit() & _withdraw()
    function authorized() external view returns (address);

    /// @notice Total amount currently deposited via _deposit()
    function totalSupply() external view returns (uint256);

    /// @notice Current amount deposited by tokenId
    function balanceOf(uint256 tokenId) external view returns (uint256);

    /// @notice Amount of tokens to reward depositors for a given epoch
    /// @param token Address of token to reward
    /// @param epochStart Startime of rewards epoch
    /// @return Amount of token
    function tokenRewardsPerEpoch(
        address token,
        uint256 epochStart
    ) external view returns (uint256);

    /// @notice Most recent timestamp a veNFT has claimed their rewards
    /// @param  token Address of token rewarded
    /// @param tokenId veNFT unique identifier
    /// @return Timestamp
    function lastEarn(
        address token,
        uint256 tokenId
    ) external view returns (uint256);

    /// @notice True if a token is or has been an active reward token, else false
    function isReward(address token) external view returns (bool);

    /// @notice The number of checkpoints for each tokenId deposited
    function numCheckpoints(uint256 tokenId) external view returns (uint256);

    /// @notice The total number of checkpoints
    function supplyNumCheckpoints() external view returns (uint256);

    /// @notice Deposit an amount into the rewards contract to earn future rewards associated to a veNFT
    /// @dev Internal notation used as only callable internally by `authorized`.
    /// @param amount   Amount deposited for the veNFT
    /// @param tokenId  Unique identifier of the veNFT
    function _deposit(uint256 amount, uint256 tokenId) external;

    /// @notice Withdraw an amount from the rewards contract associated to a veNFT
    /// @dev Internal notation used as only callable internally by `authorized`.
    /// @param amount   Amount deposited for the veNFT
    /// @param tokenId  Unique identifier of the veNFT
    function _withdraw(uint256 amount, uint256 tokenId) external;

    /// @notice Claim the rewards earned by a veNFT staker
    /// @param tokenId  Unique identifier of the veNFT
    /// @param tokens   Array of tokens to claim rewards of
    function getReward(uint256 tokenId, address[] memory tokens) external;

    /// @notice Add rewards for stakers to earn
    /// @param token    Address of token to reward
    /// @param amount   Amount of token to transfer to rewards
    function notifyRewardAmount(address token, uint256 amount) external;

    /// @notice Determine the prior balance for an account as of a block number
    /// @dev Block number must be a finalized block or else this function will revert to prevent misinformation.
    /// @param tokenId      The token of the NFT to check
    /// @param timestamp    The timestamp to get the balance at
    /// @return The balance the account had as of the given block
    function getPriorBalanceIndex(
        uint256 tokenId,
        uint256 timestamp
    ) external view returns (uint256);

    /// @notice Determine the prior index of supply staked by of a timestamp
    /// @dev Timestamp must be <= current timestamp
    /// @param timestamp The timestamp to get the index at
    /// @return Index of supply checkpoint
    function getPriorSupplyIndex(
        uint256 timestamp
    ) external view returns (uint256);

    /// @notice Get number of rewards tokens
    function rewardsListLength() external view returns (uint256);

    /// @notice Calculate how much in rewards are earned for a specific token and veNFT
    /// @param token Address of token to fetch rewards of
    /// @param tokenId Unique identifier of the veNFT
    /// @return Amount of token earned in rewards
    function earned(
        address token,
        uint256 tokenId
    ) external view returns (uint256);

    function checkpoints(
        uint256 tokenId,
        uint256 index
    ) external view returns (uint256 timestamp, uint256 balanceOf);

    function supplyCheckpoints(
        uint256 index
    ) external view returns (uint256 timestamp, uint256 supply);
}

